const TARGET_CHANGED_EVENT = 'targetChanged'

export interface DiagramFragmentDialogTarget {
    fragmentId: string | null
}

/** Owns whether sequence-fragment creation or editing dialog is open. */
export class DiagramFragmentDialogService extends EventTarget {
    private target: DiagramFragmentDialogTarget | null = null

    getTargetSnapshot = () => this.target

    subscribeTarget = (listener: () => void) => {
        this.addEventListener(TARGET_CHANGED_EVENT, listener)

        return () => this.removeEventListener(TARGET_CHANGED_EVENT, listener)
    }

    openCreate() {
        if (this.target?.fragmentId === null) return false

        this.target = { fragmentId: null }
        this.dispatchEvent(new Event(TARGET_CHANGED_EVENT))

        return true
    }

    openEdit(fragmentId: string) {
        if (fragmentId.trim().length === 0) throw new Error('Diagram fragment ID is required')
        if (this.target?.fragmentId === fragmentId) return false

        this.target = { fragmentId }
        this.dispatchEvent(new Event(TARGET_CHANGED_EVENT))

        return true
    }

    close() {
        if (!this.target) return false

        this.target = null
        this.dispatchEvent(new Event(TARGET_CHANGED_EVENT))

        return true
    }
}

export const diagramFragmentDialogService = new DiagramFragmentDialogService()

import { Dialog, DialogTitle } from '@mui/material'
import { useEffect, useSyncExternalStore } from 'react'
import { diagramEditSessionService } from '../../../services/diagrams/diagram_edit_session_service'
import { DiagramFragmentForm, type FragmentDialogSession } from './diagram_fragment_form'
import {
    diagramFragmentDialogService, type DiagramFragmentDialogService,
} from './diagram_fragment_dialog_service'

/** Creates, edits, and deletes complete sequence fragments through one service-owned dialog target. */
export function DiagramFragmentDialog({
    dialog = diagramFragmentDialogService,
    session = diagramEditSessionService,
}: {
    dialog?: DiagramFragmentDialogService
    session?: FragmentDialogSession
}) {
    const target = useSyncExternalStore(dialog.subscribeTarget, dialog.getTargetSnapshot, dialog.getTargetSnapshot)
    const fragmentExists = useSyncExternalStore(
        (listener) => session.read.subscribeCollectionMembership('fragment', listener),
        () => !target?.fragmentId || !!session.read.getFragmentSnapshot(target.fragmentId),
        () => !target?.fragmentId || !!session.read.getFragmentSnapshot(target.fragmentId),
    )
    const handleClose = () => dialog.close()

    useEffect(() => {
        if (target?.fragmentId && !fragmentExists) dialog.close()
    }, [dialog, fragmentExists, target])

    return (
        <Dialog fullWidth maxWidth="sm" onClose={handleClose} open={!!target && fragmentExists}>
            <DialogTitle>{target?.fragmentId ? 'Edit sequence fragment' : 'New sequence fragment'}</DialogTitle>
            {target && fragmentExists ? (
                <DiagramFragmentForm
                    fragmentId={target.fragmentId}
                    key={target.fragmentId ?? 'new'}
                    onClose={handleClose}
                    session={session}
                />
            ) : null}
        </Dialog>
    )
}

